"""Assessment/policy seam: a `Policy` protocol and a minimal `DispositionPolicy`.

Just enough to produce the three case states and exercise
`assessment_failed`. The full study-policy interpretation protocol, result
queries, and CLI are Item 12 (spec.md#assessment-policy-boundary);
`ModelEvidence` is never mutated.
"""
from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any, Callable, Literal, Mapping, Protocol

from simkit.evaluation.evidence import ModelEvidence

ObjectiveRole = Literal["minimize", "maximize", "penalty"]


@dataclass(frozen=True)
class ObjectiveSpec:
    """One configured objective: which output to read and how to weigh it.

    `penalty_threshold` bounds the "satisfied but beyond threshold ->
    penalize" disposition (`ObjectivePolicy`, design.md#the-policy).
    """

    output: str
    role: ObjectiveRole
    penalty_threshold: float | None = None


_DISPOSITION_BY_HEADLINE = {
    "satisfied": "feasible",
    "violated": "infeasible",
    "indeterminate": "indeterminate",
    "not_assessed": "not_assessed",
}


class AssessmentFailed(Exception):
    """Policy/objective extraction failed; the runner preserves real evidence
    for this case (spec.md#runner)."""


class Policy(Protocol):
    def assess(self, evidence: ModelEvidence, *, candidate_id: str) -> dict[str, Any]: ...


class DispositionPolicy:
    """Maps evidence to a disposition using the real canonical headline
    vocabulary (`satisfied|violated|indeterminate|not_assessed`).

    `reject_candidate_ids` is an injected set this policy raises
    `AssessmentFailed` for — the seam Item 11 needs to exercise
    `assessment_failed` against real evidence, since the deterministic
    fixture cannot itself fail assessment (design.md#validation-approach).
    """

    def __init__(self, reject_candidate_ids: frozenset[str] = frozenset()) -> None:
        self.reject_candidate_ids = reject_candidate_ids

    def assess(self, evidence: ModelEvidence, *, candidate_id: str) -> dict[str, Any]:
        if candidate_id in self.reject_candidate_ids:
            raise AssessmentFailed(f"policy rejected {candidate_id}")
        headline = evidence.responses["headline"]
        return {"disposition": _DISPOSITION_BY_HEADLINE[headline], "headline": headline}


# Headline -> disposition, the extraction-independent half of the mapping
# (design.md#the-policy step 3). "satisfied" is resolved by `ObjectivePolicy`
# itself, since it also depends on the configured penalty threshold.
_HEADLINE_DISPOSITION: Mapping[str, str] = {
    "violated": "reject",
    "indeterminate": "keep-for-boundary",
    "not_assessed": "keep-for-boundary",
}


def _beyond_penalty_threshold(objective: ObjectiveSpec, value: float) -> bool:
    if objective.penalty_threshold is None or not math.isfinite(value):
        return False
    if objective.role == "maximize":
        return value < objective.penalty_threshold
    return value > objective.penalty_threshold  # minimize | penalty


class ObjectivePolicy:
    """The real study-policy interpretation: extracts configured objectives
    and response roles from immutable evidence, then maps the headline
    verdict (plus, for "satisfied", each objective's raw value against its
    configured `penalty_threshold`) to one of the four dispositions
    (design.md#the-policy).
    """

    def __init__(
        self,
        objectives: tuple[ObjectiveSpec, ...],
        response_roles: Mapping[str, str],
        config: Any = None,
    ) -> None:
        self.objectives = tuple(objectives)
        self.response_roles = dict(response_roles)

    def assess(self, evidence: ModelEvidence, *, candidate_id: str) -> dict[str, Any]:
        objective_values: dict[str, float] = {}
        for objective in self.objectives:
            if objective.output not in evidence.outputs:
                raise AssessmentFailed(
                    f"{candidate_id}: objective output {objective.output!r} "
                    "absent from evidence.outputs"
                )
            objective_values[objective.output] = evidence.outputs[objective.output]

        for role, constraint_id in self.response_roles.items():
            if constraint_id not in evidence.responses:
                raise AssessmentFailed(
                    f"{candidate_id}: response role {role!r} names constraint "
                    f"{constraint_id!r}, absent from evidence.responses"
                )

        headline = evidence.responses["headline"]
        if headline != "satisfied":
            disposition = _HEADLINE_DISPOSITION[headline]
            return {
                "disposition": disposition, "headline": headline,
                "objectives": objective_values, "penalty": None,
            }

        for objective in self.objectives:
            value = objective_values[objective.output]
            if _beyond_penalty_threshold(objective, value):
                return {
                    "disposition": "penalize", "headline": headline,
                    "objectives": objective_values, "penalty": value,
                }
        return {
            "disposition": "feed-strategy", "headline": headline,
            "objectives": objective_values, "penalty": None,
        }


PolicyFactory = Callable[[tuple[ObjectiveSpec, ...], Mapping[str, str], Any], Policy]

# name -> factory(objectives, response_roles, policy_config). `policy_config`
# is the raw `study.config.PolicyConfig` (typed loosely here to avoid a
# policy<->config import cycle; only `ObjectivePolicy` needs it, and only for
# future per-name config, not today).
POLICY_REGISTRY: dict[str, PolicyFactory] = {
    "objective/v1": ObjectivePolicy,
}

"""Serializes `ModelEvidence` for staging (D3, INV-H, MF-3).

Isolation-clean: never imports a generated report class — reads `report`
only via `model_dump(mode="json")` (a `pydantic.BaseModel` method every
generated report has, never introspected further). The dict this module
produces is handed unchanged to `StudyStore.commit_case`, which is the
single function that turns it into both the on-disk bytes and the digest
(INV-H: one source, so the two cannot drift).
"""
from __future__ import annotations

import math
from typing import Any

from simkit.evaluation.evidence import ModelEvidence

NONFINITE_KEY = "__nonfinite__"


def _tag_nonfinite(value: Any) -> Any:
    if isinstance(value, float) and not math.isfinite(value):
        tag = "nan" if math.isnan(value) else ("inf" if value > 0 else "-inf")
        return {NONFINITE_KEY: tag}
    if isinstance(value, dict):
        if set(value) == {NONFINITE_KEY}:
            raise ValueError(
                f"reserved key {NONFINITE_KEY!r} collision in evidence payload: {value!r}"
            )
        return {key: _tag_nonfinite(val) for key, val in value.items()}
    if isinstance(value, list):
        return [_tag_nonfinite(val) for val in value]
    return value


def encode_evidence(evidence: ModelEvidence) -> dict[str, Any]:
    """Recursively sentinel-tag non-finite floats across the whole payload.

    Used for **both** the digest input and the on-disk bytes (D3) — unlike
    Item 10's `_json_safe` (`evaluator.py`), which is digest-input only and
    never read back. Rejects loudly (`ValueError`) if a genuine value is
    already a one-key `{"__nonfinite__": ...}` mapping (MF-3): the generated
    report is a typed schema that cannot emit this key, so a collision means
    an unexpected report shape that must fail rather than be papered over.
    """
    payload = {
        "responses": dict(evidence.responses),
        "outputs": dict(evidence.outputs),
        "provenance": evidence.provenance.model_dump(mode="json"),
        "report": evidence.report.model_dump(mode="json"),
    }
    return _tag_nonfinite(payload)


def _untag_nonfinite(value: Any) -> Any:
    if isinstance(value, dict):
        if set(value) == {NONFINITE_KEY}:
            return {"nan": math.nan, "inf": math.inf, "-inf": -math.inf}[value[NONFINITE_KEY]]
        return {key: _untag_nonfinite(val) for key, val in value.items()}
    if isinstance(value, list):
        return [_untag_nonfinite(val) for val in value]
    return value


def decode_evidence(payload: dict[str, Any]) -> dict[str, Any]:
    """The exact inverse of `encode_evidence`'s sentinel tagging (D5, INV-3):
    a one-key `{"__nonfinite__": ...}` dict decodes back to the real float;
    every other dict/list is recursed identically, so no sentinel-shaped
    dict leaks to the caller and no other one-key dict is ever touched.
    """
    return _untag_nonfinite(payload)

def ordered_cases(self) -> list[dict]:
    rows = self.conn.execute("SELECT * FROM cases ORDER BY commit_order").fetchall()
    return [dict(row) for row in rows]

def referenced_digests(self) -> set[str]:
    return {
        row["evidence_digest"]
        for row in self.conn.execute(
            "SELECT evidence_digest FROM cases WHERE evidence_digest IS NOT NULL"
        )
    }

# -- GC (L2-1, L3-5) -----------------------------------------------------

def gc(self) -> dict:
    """Collect orphaned staging tmps and unreferenced artifacts.

    Refuses while any lease is live: a live runner's in-flight
    `staging/{lease}/*.tmp` are untouchable. Safe to run once the lease
    is released or dead (reclaim already proved it dead).
    """
    now = time.time()
    row = self.conn.execute("SELECT * FROM runner_lease WHERE singleton = 1").fetchone()
    if row is not None and not row["released"] and not self._lease_is_dead(row, now):
        raise StudyLocked("GC refused: a runner lease is live")

    referenced = self.referenced_digests()
    tmps_collected = 0
    for lease_dir in sorted(p for p in self.staging_dir.glob("*") if p.is_dir()):
        for tmp in lease_dir.glob("*.tmp"):

def _assess_and_commit(
    self, evidence: ModelEvidence, candidate_id: str, proposal_id: str, attempt_id: str,
    attempt_number: int, canonical_inputs: Mapping,
) -> None:
    evidence_json = encode_evidence(evidence)
    try:
        assessment = self.definition.policy.assess(evidence, candidate_id=candidate_id)
    except AssessmentFailed as error:
        self.store.commit_case(
            candidate_id=candidate_id, proposal_id=proposal_id, attempt_id=attempt_id,
            state="assessment_failed", inputs=canonical_inputs, evidence_json=evidence_json,
            assessment_json={"failure": str(error)}, crash=self.crash,
        )
        self.store.record_transition(
            attempt_id=attempt_id, candidate_id=candidate_id, proposal_id=proposal_id,
            attempt_number=attempt_number, state="assessment_failed",
        )
        return

    self.store.commit_case(
        candidate_id=candidate_id, proposal_id=proposal_id, attempt_id=attempt_id,
        state="completed", inputs=canonical_inputs, evidence_json=evidence_json,
        assessment_json=assessment, crash=self.crash,
    )
    self.store.record_transition(
        attempt_id=attempt_id, candidate_id=candidate_id, proposal_id=proposal_id,
        attempt_number=attempt_number, state="committed",
    )

def _record_transition_best_effort(
    self, attempt_id: str, candidate_id: str, proposal_id: str, attempt_number: int,
    state: str,
) -> None:
    try:
        self.store.record_transition(
            attempt_id=attempt_id, candidate_id=candidate_id, proposal_id=proposal_id,
            attempt_number=attempt_number, state=state,
        )
    except RetryableStoreError:
        pass  # forensics only; the retry loop proceeds regardless

"""`BoundedStrategy`: caps an inner strategy's proposals at `max_candidates`
(D9). Additive — a bounded study's `config_fingerprint` folds in both the
inner strategy's config and the bound, so it is a distinct lineage from the
unbounded study by construction.
"""
from __future__ import annotations

from typing import Any, Iterable, Mapping

from .identity import digest_of


class BoundedStrategy:
    def __init__(self, inner: Any, max_candidates: int) -> None:
        self.inner = inner
        self.max_candidates = max_candidates
        self.identity = f"{inner.identity}+bounded/v1"

    def config_fingerprint(self) -> str:
        return digest_of(
            {"inner": self.inner.config_fingerprint(), "max_candidates": self.max_candidates}
        )

    def propose(self, study_id: str) -> Iterable[tuple[str, Mapping[str, Any]]]:
        for index, item in enumerate(self.inner.propose(study_id)):
            if index >= self.max_candidates:
                return
            yield item

    def observe(self, feedback: Any) -> None:
        self.inner.observe(feedback)
